stealToggle.btn.MouseButton1Click:Connect(function() stealOn=not stealOn if stealOn then if next(selected)==nil then Window.Notify("ERROR","Pilih Rarity dulu!",Color3.fromRGB(248,113,113),3) stealOn=false return end tw(stealToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(stealToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(stealToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() walkToSafeBase() task.spawn(function() while stealOn do local list=getStealTargets() local found=#list>0 for _,m in ipairs(list) do if not stealOn then break end pcall(function() stealMethod(m) end) task.wait(0.5) end if not found then task.wait(0.8) end end end) else tw(stealToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(stealToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(stealToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() stealOn=false end end)
