local function resetCharOnce() pcall(function() local char=plr.Character local hum=char and char:FindFirstChildOfClass("Humanoid") if hum then hum.Health=0 else if char then char:BreakJoints() end end end) end
halloweenToggle.btn.MouseButton1Click:Connect(function() halloweenEnabled=not halloweenEnabled if halloweenEnabled then tw(halloweenToggle.track,{BackgroundColor3=Color3.fromRGB(255,140,0)},0.2):Play() tw(halloweenToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(halloweenToggle.accent,{BackgroundColor3=Color3.fromRGB(255,140,0)},0.2):Play() Window.Notify("HALLOWEEN","Auto Halloween ON",Color3.fromRGB(255,140,0),2) task.spawn(function() while halloweenEnabled do local clue,pos=getClosestClue() if clue and pos then cachedCluePos=pos lastClueSeen=tick() if not halloweenActive then halloweenActive=true hasResetThisEvent=false Window.Notify("HALLOWEEN","Event Muncul! Reset Char 1x",Color3.fromRGB(255,140,0),3) end if not hasResetThisEvent then hasResetThisEvent=true resetCharOnce() task.wait(2) -- tunggu respawn continue end -- walk ke target pake sistem walkDirect yang udah ada
                local targetPos=V3(pos.X,3.5,pos.Z) pcall(function() walkDirect(targetPos,pos,false) end) Window.Notify("HALLOWEEN","Diem "..halloweenStay.."s di clue",ACCENT,1) task.wait(halloweenStay) else if halloweenActive and (tick()-lastClueSeen)>10 then halloweenActive=false hasResetThisEvent=false cachedCluePos=nil Window.Notify("HALLOWEEN","Event Selesai (10s no clue) - Balik Break Egg",DIM,3) end task.wait(0.5) end end end) else tw(halloweenToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(halloweenToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(halloweenToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() halloweenActive=false hasResetThisEvent=false Window.Notify("HALLOWEEN","OFF",DIM,2) end end)

